<?php
namespace App\Filament\Pages;
use App\Models\Setting; use App\Services\AdminAudit; use Filament\Forms\Components\{Textarea,TextInput,Toggle}; use Filament\Notifications\Notification; use Filament\Pages\Page; use Filament\Schemas\Components\Section; use Filament\Schemas\Schema;
class ContactSettingsPage extends Page { protected static ?string $slug='contact-settings'; protected static ?string $title='Réglages Contact'; protected static string|\BackedEnum|null $navigationIcon='heroicon-o-cog-6-tooth'; protected static string|\UnitEnum|null $navigationGroup='Contact'; protected static ?string $navigationLabel='Réglages'; protected static ?int $navigationSort=2; protected string $view='filament.pages.settings-page'; public ?array $data=[]; public function mount():void{$this->form->fill((array)(Setting::where('key','contact_settings')->value('value')??[]));} public function form(Schema $schema):Schema{return $schema->components([Section::make()->schema([TextInput::make('recipient')->label('Destinataire unique')->email()->required(),Textarea::make('introduction')->label('Texte d’introduction')->maxLength(2000),Textarea::make('success_message')->label('Message après envoi')->maxLength(500),Toggle::make('send_confirmation')->label('Envoyer un accusé de réception')])])->statePath('data');} public function save():void{Setting::updateOrCreate(['key'=>'contact_settings'],['group'=>'contact','value'=>$this->form->getState()]);app(AdminAudit::class)->record('contact.settings.updated','contact_settings');Notification::make()->title('Réglages enregistrés')->success()->send();}}
